from itertools import count


class Database:
    def __init__(self) -> None:
        self.tables: dict[str, list[dict]] = {}
        self._ids = count(1)

    def insert(self, table: str, row: dict) -> int:
        row = {"id": next(self._ids), **row}
        self.tables.setdefault(table, []).append(row)
        return row["id"]

    def find_one(self, table: str, **filters) -> dict | None:
        for row in self.tables.get(table, []):
            if all(row.get(k) == v for k, v in filters.items()):
                return row
        return None

    def get(self, table: str, row_id: int) -> dict | None:
        return self.find_one(table, id=row_id)

    def update(self, table: str, row_id: int, values: dict) -> bool:
        row = self.get(table, row_id)
        if row is None:
            return False
        row.update({k: v for k, v in values.items() if k != "id"})
        return True

